from functools import wraps

def laut(funktion):
    @wraps(funktion)
    def wrapper(*args, **kwargs):
        return funktion(*args, **kwargs).upper()
    return wrapper

@laut
def hallo(name):
    return f"Hallo {name}"

print(hallo("Ada"))

class Konto:
    def __init__(self):
        self._punkte = 0
    @property
    def punkte(self):
        return self._punkte
    @punkte.setter
    def punkte(self, wert):
        if wert < 0:
            raise ValueError("Punkte dürfen nicht negativ sein")
        self._punkte = wert

k = Konto()
k.punkte = 7
print(k.punkte)

