def two_sum(werte, ziel):
    gesehen = {}
    for i, wert in enumerate(werte):
        rest = ziel - wert
        if rest in gesehen:
            return gesehen[rest], i
        gesehen[wert] = i
    return None

print(two_sum([2, 7, 11, 15], 9))
print(two_sum([3, 3], 6))

