def gueltig(text):
    paare = {")": "(", "]": "[", "}": "{"}
    stapel = []
    for zeichen in text:
        if zeichen in "([{":
            stapel.append(zeichen)
        elif zeichen in paare:
            if not stapel or stapel.pop() != paare[zeichen]:
                return False
        else:
            return False
    return not stapel

print(gueltig("([])"))
print(gueltig("([)]"))

from collections import deque

graph = {"A": ["B", "C"], "B": ["D"], "C": ["D"], "D": []}
entfernung = {"A": 0}
queue = deque(["A"])
while queue:
    aktuell = queue.popleft()
    for nachbar in graph[aktuell]:
        if nachbar not in entfernung:
            entfernung[nachbar] = entfernung[aktuell] + 1
            queue.append(nachbar)
print(entfernung["D"])

def schritte(n):
    anzahl = 0
    for _ in range(n):
        for _ in range(n):
            anzahl += 1
    return anzahl

print(schritte(4))
